import pathlib,json,hashlib,datetime,re,os,subprocess
L=pathlib.Path(__file__).resolve().parent
H=lambda b:hashlib.sha256(b).hexdigest()
P=json.loads((L/'literal-provenance.json').read_text());R=json.loads((L/'reservation.json').read_text())
def save(n,x): (L/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
notes={
359026:('exclude_literal_normalization_correction','Section 2 identity/non-normalizability; Section 3.1 Conjecture 1; v1 and v2 retrieved','I_3 diagonalizes the edgeless three-vertex Laplacian, with pairwise orthogonal ternary columns and all eigenvalue multiplicities equal. This is the omitted-normalization reading; intended normalized problem unresolved.','Definitions and local proof bodies; old version fetched and text inspected locally.'),
359157:('exclude_public_source_formula_correction','Conjecture 13, Proposition 14 and Section 5 four-case proof','Literal coefficient on the second double sum is 1, while the proved k=2 specialization has 2. At n=5 public enumeration gives 70 and literal RHS 64. Complete bridge in ORDINARY_ATTEMPTS.md; no new credit.','Definitions, actual four-case proof and statement; v1 and v2 retrieved.'),
359270:('park_flagship_no_full_route','arXiv:2307.12681 latest PDF','Cycle double cover is an all-bridgeless-graphs endpoint; a local face graph construction does not provide a global cycle pairing. No grouping/gluing theorem or exact obstruction obtained. No inference of open status from 2023 metadata.','Literal read and live abstract; latest PDF retrieved/text extracted, not substantive proof-body review.'),
359362:('park_analytic_existence_gap','arXiv:2308.00811 Section 6.3 Conjecture 6.3','Finitely supported load does not make the boundary finite. Compactness of measure-valued optimizers alone does not put the joint support in (boundary union load support)^2. Need endpoint relocation preserving equilibrium and optimum plus existence; none proved.','Literal and live abstract; source concluding context inspected, optimization definitions/proofs not fully reviewed.'),
359750:('park_membrane_topology_gap','arXiv:2309.00100v3 Conjecture 4.3','The source explicitly explains why horizontal strips of minimal membranes may contain cycles instead of the tree structure of Lemma 2.3. The generalized-grid-polygon bound does not extend automatically; both bound and equality classification remain unpaid.','Actual conjecture and source obstruction paragraph read; full membrane definitions and figures not visually reviewed.'),
360138:('park_scope_and_generality_gap','arXiv:2309.16061 Remark 2.11 and Conjecture 2.9 context','The source reports results for skew-symmetric and orbifold-associated cases. Literal record also conflates full seed determination with unique cluster neighbor and omits ambient algebra hypotheses. No full general coefficient/seed proof obtained; no scope correction promoted.','Literal, live abstract, actual source conjecture neighborhood and cited case distinctions; no global cluster proof review.'),
360291:('exclude_public_full_construction','arXiv:2310.06464 Conjecture 1; ProbXiv public solution 2026-08-17','Public all-r construction with monochromatic core, propagation path, vertex-deletion colorings and edge-minimization gives the whole existence endpoint. Source only proves r=3, but public solution is general. See ordinary bridge.','Actual primary definitions, Conjecture 1 and source construction context; complete public solution body read and construction reasoned through.'),
360957:('park_sustained_marked_factor_gap','arXiv:2311.18227v1/v2/v3; DMTCS 26:1 #7','Newton inversion proves only equivalence of formulas. A multismall-label insertion-stable primitive-factor bijection with at most a-1 marked factors remains unproved. Three repairs and exact gap in ORDINARY_ATTEMPTS.md.','All available arXiv versions target sections; v3 primitive definitions and Theorems 2.6/3.2 proof bodies; identical journal PDF verified.'),
361039:('park_full_conjunction_unproved','arXiv:2312.03564v2 Definition 3.1, 3.22, Conjecture 3.27','Four enumerations must all be resolved; the 132-avoiding permutation subfamily does not exhaust matrices with negative entries. Positive inversion equals inv minus negative-one count, so bounding inv alone does not classify the posinv=1,2 fibers. No whole-conjunction classification or refutation.','Actual square sign/magog definitions, inversion statistic, neighboring extremal proof and printed table text; v1 fetched. Journal landing page fetched, no full journal audit.'),
361121:('park_geometric_classification_gap','arXiv:2312.08262 Conjecture 2 and Figure 19 caption','Must cover every Penrose caterpillar by the stated poset/boat-derived-path alternatives. An optimal worm construction does not classify all shapes or provide the required containment. No exact witness outside both alternatives; pictures not visually audited.','Literal, live abstract, actual conjecture and local boat-transform context; not all tiling definitions/proofs.'),
361271:('park_sustained_infinite_support_gap','arXiv:2312.14888v1 Conjecture 4.5; v2 and NYJM Conjecture 4.7','Source three-summand theorem and finite-minimum-gap two-summand case already public. Arbitrary infinite repeated minimum gaps with prefix remain. Unique interior minimum and merging irreducibles both fail; full analysis in ORDINARY_ATTEMPTS.md.','Semidomain and series definitions; Lemmas 4.1-4.3, Theorem 4.4 proof, Example 4.6, Conjecture 4.7 and Proposition 4.8 inspected; v1/v2 and typeset target compared.'),
382247:('park_semicover_boundary_gap','arXiv:2311.01672v2 Conjecture 2 and Lemma 4 context','Bound n<14 for full covers is not nonexistence of all semi-covers. Paths can terminate on boundary; Euler charge cannot silently impose full-cover degree there. Need boundary-compatible charge or an exact labeled planar object satisfying every clause. Neither obtained.','Literal, live abstract, actual Conjecture 2 and bead/necklace context; no exhaustive Lemma 4/figure verification.'),
359387:('exclude_public_source_theorem','arXiv:2308.02327 Theorem 1.2, Section 5','Theorem 1.2 proves identical Conjecture 1.1 chains. The source combines explicit errors with finite checks, not independently rerun here. No new credit.','The eleven-chain statement, theorem, generating definitions and proof structure/finite-check dependency inspected.'),
364307:('exclude_public_source_theorem','arXiv:2408.05066 Theorems 4 and 6','Theorem 6 is exactly the conjecture; induced shortest odd cycles plus source-at-apex parity obstruction prove necessity, directed paths of length at most two prove bipartite sufficiency.','Entire six-page source text read, including definitions and full main proofs; figures read as labels/text, not rendered.'),
364392:('exclude_public_full_proof_claim_with_limits','arXiv:2408.09152v2 Conjecture 4.1; public manuscript 2026-11-04 v0.2.0-candidate','Public weighted singleton/pair theorem specializes with weights one to all dependent-set counts. Main marked-downset, critical-element and conditional antipodal-pairs proof inspected. External Katona/Kahn-Neiman bodies not audited; no new discovery.','Primary definitions and conclusion; main public proof Sections 1-4 inspected. Latest journal landing page retrieved; PDF link returned HTML viewer, not a proof PDF.'),
372783:('park_general_permanence_gap','arXiv:2601.18742 Sections 3.3 and 6.3','Scalar/matrix approximation closure under direct sums does not imply free-product closure; the record explicitly warns of a gap. Need uniform nontriviality and multiplicative-error control for reduced words and all graph commutations. No full mechanism.','Literal and live abstract; graph-product normal-form and halo context inspected, no full approximation proof review.'),
372784:('park_general_permanence_gap','arXiv:2601.18742 Sections 3.5 and 6.3','A finite group metric approximate model for each vertex group does not supply a simultaneous graph-product model with controlled word separation. A graph product of finite groups need not be finite. No full closure theorem proved.','Literal and live abstract; graph-product normal-form context inspected, not all weakly-sofic definitions/proofs.'),
373538:('exclude_public_stronger_source_theorem','arXiv:2603.10316 Theorems 3.1,3.3 and Corollary 3.5','ker subset core; source bounds corona+core by 2alpha plus vertex-distinct odd-cycle count, which is at most all odd cycles. Complete exact bridge and source proof inspected.','Actual graph/critical-set definitions and Theorem 3.3 proof read; companion 2603.10315 fetched but not independently proof-audited.'),
375393:('park_sustained_scalar_to_block_gap','arXiv:2606.17974 Section 5; original 2405.04119 and companion 2602.24171','Need every t by t edge-matrix labeling to have a simultaneous td-dimensional Gram representation, where d is scalar inversion diameter. Entrywise lifting costs too much; extension-field matrices are not arbitrary; rank alone loses characteristic-two form type. Full gap detailed in ORDINARY_ATTEMPTS.md.','Actual inversion/Gram bridge, Lemmas 5.2-5.4 and forest/cycle proof read; original and companion fetched and limited target text screened.'),
375796:('exclude_public_source_refutation_version_qualified','arXiv:2607.04141v3 Theorem 5.7','The complement of C7 has lrw=2 and lsfw=8, contradicting bound 6. Actual fourth-birth/fold obstruction read. Definitions changed across versions; old-vs-new semantic equivalence not globally cleared.','Latest source counterexample and actual proof body read; v1/v2 not obtained, so full version-fidelity gate remains qualified.')}
results={}
chunkcache={}
for i in R['ids']:
 k=str(i);x=P[k];raw=(L/'raw'/f'{k}.jsonl').read_bytes();assert raw.endswith(b'\n') and H(raw)==x['raw_sha256']
 q=pathlib.Path(x['chunk'])
 if str(q) not in chunkcache:chunkcache[str(q)]=q.read_bytes()
 b=chunkcache[str(q)];assert H(b)==x['chunk_sha256'];assert b.splitlines(keepends=True)[x['line']-1]==raw
 x['raw_file']=f'raw/{k}.jsonl';x['raw_newline_preserved']=True;x['record_utf8_without_terminal_newline_sha256']=H(raw[:-1]);x['parsed_record_canonical_json_sha256']=H(json.dumps(x['record'],sort_keys=True,ensure_ascii=False,separators=(',',':')).encode());assert x['statement_sha256']==H(x['record']['statement'].encode())
 d,loc,reason,depth=notes[i]
 results[k]={'mathdb_id':i,'title':x['record']['title'],'literal_statement':x['record']['statement'],'full_parsed_record':x['record'],'provenance':{a:v for a,v in x.items() if a!='record'},'disposition':d,'reason':reason,'actual_read_depth':depth,'source_locators':loc,'ordinary_attempts_file':'ORDINARY_ATTEMPTS.md','historical_check':'Exact 262-file allowlist plus authorized ledger/STATUS/context metadata; see history-inventory.json and history-matches.json. No recursive history scan.','literature_clearance':False,'qualification_limits':['Current registry pages/README/import/projects indexes are bounded routing checks, not complete proof-body clearance.','Not every citing paper, journal correction or source figure was read. Missing coverage is not clearance.'],'candidate':False,'pi_execution_qualified':False,'lean_execution_performed':False,'accepted_credit':0}
assert set(results)==set(map(str,R['ids'])) and len(results)==20
save('literal-provenance.json',P);save('results.json',results)
receipts=list(map(json.loads,(L/'http-receipts.jsonl').read_text().splitlines()))
inventory=[]
for r in receipts:
 if r.get('status')!=200:inventory.append({'url':r['url'],'depth':'failed access','error':r.get('error')});continue
 p=L/r['artifact'];b=p.read_bytes();assert len(b)==r['bytes'] and H(b)==r['sha256']
 if b.startswith(b'%PDF'):kind='PDF retrieved; text extracted where recorded; semantic depth per results.json'
 elif 'raw.githubusercontent' in r['url']:kind='bounded complete text/index term screen; not proof review'
 elif '/abs/' in r['url']:kind='metadata and version history'
 else:kind='HTML public page; target-specific depth per results.json'
 inventory.append({**r,'depth':kind})
save('source-read-inventory.json',inventory)
