save('search-read-inventory.json',{'depth':'Managed search result excerpts; primary bodies separately fetched via capped HTTP. Search results alone never clear a candidate.','queries':['LeanPool projects.yml github','Omega trureturing github math proofs','dependence polynomials ultra log concavity proof counterexample','On the colorability of bi-hypergraphs minimal uncolorable uniform','2312.14888 Conjecture proof','Conjecture 3.27 magog','lexicographic inversion diameter conjecture proof','2307.01859 odd Hadamard conjecture','site.nyjm.albany.edu Goldbach theorem for Laurent','A positional statistic conjecture proof','Totally symmetric self-complementary inversion conjecture proof','Diameter of the inversion graph Havet Horsch Rambaud arxiv','A positional statistic correction','Goldbach theorem for Laurent series semidomains correction'],'limits':'Result sets bounded, broad query noise retained in tool transcript; no exhaustive corrections/citing coverage.'})
